"""
Allows users to send gripper actions.
"""

import ctypes
import threading

from typing import Callable, Any
from enum import IntEnum

from ...cmavsdk_loader import _cmavsdk_lib
from ...exceptions import MavsdkError


# ===== Enums =====
class GripperAction(IntEnum):
    """Gripper Actions.

    Available gripper actions are defined in mavlink under
    https://mavlink.io/en/messages/common.html#GRIPPER_ACTIONS"""

    RELEASE = 0
    GRAB = 1


# ===== Result Enums =====
class GripperResult(IntEnum):
    """Possible results returned for gripper action requests."""

    UNKNOWN = 0
    SUCCESS = 1
    NO_SYSTEM = 2
    BUSY = 3
    TIMEOUT = 4
    UNSUPPORTED = 5
    FAILED = 6


class GripperError(MavsdkError):
    """Raised when a Gripper request fails.

    Attributes
    ----------
    result : GripperResult
        The result the request failed with.
    origin : str
        The method that failed.
    params : tuple
        The arguments the method was called with.
    """

    def __init__(self, result, origin, *params):
        super().__init__(result, origin, *params)
        self.result = result
        self.origin = origin
        self.params = params

    def __str__(self):
        return f"{self.result.name}; origin: {self.origin}; params: {self.params}"


